contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: take a callee address, calldata, and an amount to attempt to send from this contract to C via a call into C (not used by C.forward because forward does not be payable-receive funds from caller here)
    function run(address callee, bytes calldata data, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        // record balance of this test contract before interacting with c
        uint256 before = address(this).balance;

        // perform the forward call; capture whether it reverts
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // after call balance must be >= before - amount (i.e., the test contract did not pay Ether to C by this call)
        // We avoid underflow by expressing the condition without subtraction: address(this).balance + amount >= before
        assert(address(this).balance + amount >= before);
    }

    receive() external payable {}
}

